const $=(q,el=document)=>el.querySelector(q), $$=(q,el=document)=>[...el.querySelectorAll(q)];
const KRW=new Intl.NumberFormat('ko-KR',{style:'currency',currency:'KRW',maximumFractionDigits:0});
const icons={utensils:'🍴',home:'⌂',car:'◆',signal:'◉',shield:'⬡',activity:'⚡',heart:'♥',sparkles:'✦',book:'▤',bulb:'♢',reserve:'●',percent:'%'};
const today=new Date().toISOString().slice(0,10), month=today.slice(0,7);
const state={user:'병호',authenticated:false,categories:[
  {id:1,name:'주거·관리비',icon:'home',color:'#22c55e'},{id:2,name:'식비·장보기',icon:'utensils',color:'#f59e0b'},{id:3,name:'교통·주유',icon:'car',color:'#38bdf8'},{id:4,name:'통신·구독',icon:'signal',color:'#60a5fa'},{id:5,name:'보험',icon:'shield',color:'#a78bfa'},{id:6,name:'태권도',icon:'activity',color:'#fb7185'},{id:7,name:'영어',icon:'book',color:'#818cf8'},{id:8,name:'의료·교육 비정기',icon:'heart',color:'#f472b6'},{id:9,name:'공과금·생활용품',icon:'bulb',color:'#34d399'},{id:10,name:'외식·쇼핑·여가',icon:'sparkles',color:'#facc15'},{id:11,name:'비상예비비',icon:'reserve',color:'#94a3b8'},{id:12,name:'금융이자',icon:'percent',color:'#f97316'}],
 budgets:[{category_id:1,budget:1200000,spent:720000},{category_id:2,budget:900000,spent:424000},{category_id:3,budget:450000,spent:178000},{category_id:4,budget:180000,spent:129000},{category_id:5,budget:420000,spent:420000},{category_id:6,budget:180000,spent:180000},{category_id:7,budget:280000,spent:280000},{category_id:8,budget:300000,spent:94000},{category_id:9,budget:380000,spent:165000},{category_id:10,budget:600000,spent:336000},{category_id:11,budget:300000,spent:0},{category_id:12,budget:220000,spent:154000}],
 transactions:[{type:'expense',title:'이마트 장보기',amount:87400,managementMonth:month,actualDate:today,category_id:2,user:'영원'},{type:'expense',title:'주유소',amount:70000,managementMonth:month,actualDate:today,category_id:3,user:'병호'},{type:'income',title:'9월 급여',amount:3800000,managementMonth:month,actualDate:month+'-25',category_id:11,user:'병호'},{type:'expense',title:'아이 책 구매',amount:46000,managementMonth:month,actualDate:month+'-24',category_id:8,user:'영원'},{type:'income',title:'프로젝트 수입',amount:2400000,managementMonth:month,actualDate:month+'-21',category_id:11,user:'영원'}],
 loans:[{id:'loan1',name:'우리집 주택담보대출',lender:'우리은행',principal:212650000,balance:186500000,rate:3.48},{id:'loan2',name:'자동차 할부',lender:'현대캐피탈',principal:32000000,balance:18400000,rate:4.2}]};
window.openBudgetModal=(type)=>openModal(type);

function saveDemo(){localStorage.setItem('bloom-budget-data',JSON.stringify({categories:state.categories,budgets:state.budgets,transactions:state.transactions,loans:state.loans,savedAt:new Date().toISOString()}));}
function loadDemo(){try{Object.assign(state,JSON.parse(localStorage.getItem('bloom-budget-data'))||{})}catch{}}
async function hash(v){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(v));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}
function cat(id){return state.categories.find(c=>Number(c.id)===Number(id))||state.categories.at(-1)}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2200)}

$$('.person').forEach(b=>b.onclick=()=>{$$('.person').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.user=b.dataset.user});
$('#show-pass').onclick=()=>{const p=$('#password');p.type=p.type==='password'?'text':'password'};
$('#login-form').onsubmit=async e=>{e.preventDefault();$('#login-error').textContent='';try{const r=await fetch('/api/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({username:state.user,password:$('#password').value})});if(r.ok)return enter();}catch{}if(await hash($('#password').value)==='c44f0f49c57e37e8a3005080b193d5ef4571dc6082b725271e0e6838744aa4a3'){enter();toast('데모 모드로 로그인했습니다')}else $('#login-error').textContent='비밀번호를 확인해 주세요.'};
function enter(){state.authenticated=true;sessionStorage.setItem('bb_user',state.user);$('#login').classList.add('hidden');$('#app').classList.remove('hidden');$('#profile-name').textContent=$('#header-name').textContent=state.user;$('.avatar').textContent=state.user[0];render()}
$('#logout').onclick=async()=>{try{await fetch('/api/logout',{method:'POST'})}catch{}sessionStorage.removeItem('bb_user');location.reload()};
$('#month').value=month;$('#menu').onclick=()=>$('.sidebar').classList.toggle('open');

function render(){
 const selectedMonth=$('#month').value,monthBudgets=state.budgets.filter(x=>(x.month||month)===selectedMonth),budget=monthBudgets.reduce((s,x)=>s+Number(x.budget),0),expense=state.transactions.filter(x=>x.type==='expense'&&(x.managementMonth||x.date?.slice(0,7))===selectedMonth).reduce((s,x)=>s+Number(x.amount),0),income=state.transactions.filter(x=>x.type==='income'&&(x.managementMonth||x.date?.slice(0,7))===selectedMonth).reduce((s,x)=>s+Number(x.amount),0),pct=budget?Math.min(100,expense/budget*100):0;
 $('#total-budget').textContent=KRW.format(budget);$('#remaining').textContent=KRW.format(Math.max(0,budget-expense));$('#spent').textContent=pct.toFixed(1)+'%';$('#main-progress').style.width=pct+'%';$('#income-total').textContent=KRW.format(income);
 $('#loan-total').textContent=KRW.format(state.loans.reduce((s,x)=>s+Number(x.balance),0));
 $('#budget-list').innerHTML=monthBudgets.map(b=>{const c=cat(b.category_id),spent=state.transactions.filter(t=>t.type==='expense'&&t.category_id==b.category_id&&(t.managementMonth||t.date?.slice(0,7))===selectedMonth).reduce((s,t)=>s+Number(t.amount),0),p=b.budget?Math.min(100,spent/b.budget*100):0;return `<div class="budget-item"><span>${p.toFixed(0)}%</span><div class="row"><div class="cat-icon" style="background:${c.color}18;color:${c.color}">${icons[c.icon]}</div><div class="name"><b>${c.name}</b><span>${KRW.format(spent)} / ${KRW.format(b.budget)}</span></div></div><div class="progress"><i style="width:${p}%;background:${c.color}"></i></div></div>`}).join('')||'<p class="empty-copy">이 관리 년월에 등록된 예산이 없습니다.</p>';
 $('#loan-list').innerHTML=state.loans.map(l=>{const p=Math.max(0,Math.min(100,(1-l.balance/l.principal)*100));return `<div class="loan-box"><div class="loan-head"><div><h4>${l.name}</h4><small>${l.lender} · ${l.rate}%</small></div><strong>${KRW.format(l.balance)}</strong></div><div class="progress"><i style="width:${p}%"></i></div><div class="loan-stats"><span>${p.toFixed(1)}% 상환</span><span>원금 ${KRW.format(l.principal)}</span></div></div>`}).join('');
 $('#recent-list').innerHTML=state.transactions.slice(0,5).map(t=>{const inc=t.type==='income',c=inc?{name:'수입',icon:'reserve',color:'#58f3c5'}:cat(t.category_id),actual=t.actualDate||t.date,managed=t.managementMonth||actual?.slice(0,7);return `<div class="transaction"><div class="transaction-icon" style="background:${c.color}18;color:${c.color}">${inc?'↙':icons[c.icon]}</div><div><b>${t.title}</b><p>${c.name} · 사용 ${actual?.replaceAll('-','.')} · 귀속 ${managed?.replace('-','.')} · ${t.user}</p></div><div class="transaction-actions"><strong class="${inc?'income-color':''}">${inc?'+':'-'} ${KRW.format(t.amount)}</strong>${inc?'':`<button data-edit-id="${t.id}" aria-label="${t.title} 수정">수정</button>`}</div></div>`}).join('');
}

const templates={
 budget:()=>`<h3 id="modal-title">월 예산 한 번에 등록</h3><p class="sub">유형명과 예산을 한 화면에서 수정하고 저장해요</p><form id="entry-form"><div class="budget-month"><label>관리 년월</label><input name="month" type="month" value="${$('#month').value||month}" required></div><div class="budget-editor"><div class="budget-edit-head"><span>소비유형</span><span>월 예산</span></div>${state.categories.map(c=>{const b=state.budgets.find(x=>x.category_id==c.id&&(x.month||month)===($('#month').value||month));return `<div class="budget-edit-row"><span class="cat-icon" style="background:${c.color}18;color:${c.color}">${icons[c.icon]}</span><input name="category_${c.id}" value="${c.name}" aria-label="${c.name} 유형명" required><div class="money-input"><span>₩</span><input name="amount_${c.id}" type="number" min="0" value="${b?.budget||0}" aria-label="${c.name} 예산" required></div></div>`}).join('')}</div><button class="primary submit">모든 예산 저장</button></form>`,
 income:()=>txForm('수입 등록','이번 달 들어온 돈을 기록해요','income'),expense:()=>txForm('지출 등록','소비유형을 선택해 명확히 기록해요','expense'),
 history:()=>historyTemplate(),
 loan:()=>formShell('대출 등록','대출 조건과 원금을 기록해요',`<div class="field"><label>대출명</label><input name="name" required placeholder="주택담보대출"></div><div class="field"><label>금융기관</label><input name="lender" required placeholder="우리은행"></div><div class="field"><label>대출 원금</label><input name="principal" type="number" min="1" required></div><div class="field"><label>금리 (%)</label><input name="rate" type="number" step="0.001" min="0" required></div><div class="field"><label>시작일</label><input name="startDate" type="date" value="${today}" required></div><div class="field"><label>만기일</label><input name="dueDate" type="date"></div>`),
 repayment:()=>formShell('대출 상환 등록','원금과 이자를 나눠 기록해요',`<div class="field wide"><label>대출</label><select name="loanId">${state.loans.map(x=>`<option value="${x.id}">${x.name}</option>`).join('')}</select></div><div class="field"><label>원금 상환액</label><input name="principalAmount" type="number" min="0" required></div><div class="field"><label>이자</label><input name="interestAmount" type="number" min="0" value="0" required></div><div class="field wide"><label>상환일</label><input name="date" type="date" value="${today}" required></div>`),
 gemini:()=>`<h3 id="modal-title">Gemini API 연결</h3><p class="sub">모델을 선택하고 API 키의 연결 상태를 확인해요</p><form id="entry-form"><div class="form-grid"><div class="field wide"><label>모델</label><select name="model"><option>gemini-2.5-flash</option><option>gemini-2.5-pro</option><option>gemini-2.0-flash</option></select></div><div class="field wide"><label>API 키</label><input name="apiKey" type="password" placeholder="AIza..." required autocomplete="off"></div></div><button class="primary submit">연결 테스트</button><div id="gemini-status" class="gemini-status">API 키는 화면에 저장하지 않습니다.</div></form>`
};
function catOptions(){return state.categories.map(c=>`<option value="${c.id}">${icons[c.icon]} ${c.name}</option>`).join('')}
function formShell(title,sub,fields){return `<h3 id="modal-title">${title}</h3><p class="sub">${sub}</p><form id="entry-form"><div class="form-grid">${fields}</div><button class="primary submit">저장하기</button></form>`}
function txForm(title,sub,type){return formShell(title,sub,`<input type="hidden" name="type" value="${type}"><div class="field wide"><label>내용</label><input name="title" required placeholder="${type==='income'?'급여':'장보기'}"></div><div class="field"><label>금액</label><input name="amount" type="number" min="1" required></div>${type==='expense'?`<div class="field"><label>소비유형</label><select name="categoryId">${catOptions()}</select></div>`:''}<div class="field"><label>관리 년월</label><input name="managementMonth" type="month" value="${$('#month').value||month}" required></div><div class="field"><label>실제 ${type==='income'?'입금일':'사용일'}</label><input name="actualDate" type="date" value="${today}" required></div><div class="field wide"><label>메모</label><input name="memo" placeholder="선택 입력"></div>`) }

function historyTemplate(){const selected=$('#month').value,items=state.transactions.filter(t=>t.type==='expense'&&(t.managementMonth||t.date?.slice(0,7))===selected);return `<h3 id="modal-title">${selected.replace('-','년 ')}월 지출 내역</h3><p class="sub">등록한 지출을 확인하고 수정할 수 있어요</p><div class="history-list">${items.length?items.map(t=>{const c=cat(t.category_id),d=t.actualDate||t.date;return `<div class="history-row"><span class="cat-icon" style="background:${c.color}18;color:${c.color}">${icons[c.icon]}</span><div><b>${t.title}</b><p>${c.name} · ${d?.replaceAll('-','.')}</p></div><strong>${KRW.format(t.amount)}</strong><button data-edit-id="${t.id}">수정</button></div>`}).join(''):'<div class="history-empty">이 관리 년월에 등록된 지출이 없습니다.</div>'}</div>`}

function openTransactionEditor(id){const t=state.transactions.find(x=>x.id===id);if(!t)return;const c=cat(t.category_id);$('#modal-body').innerHTML=`<h3 id="modal-title">지출 수정</h3><p class="sub">변경한 내용은 저장 즉시 대시보드에 반영됩니다</p><form id="entry-form"><input type="hidden" name="id" value="${t.id}"><div class="form-grid"><div class="field wide"><label>내용</label><input name="title" value="${t.title}" required></div><div class="field"><label>금액</label><input name="amount" type="number" min="1" value="${t.amount}" required></div><div class="field"><label>소비유형</label><select name="categoryId">${state.categories.map(x=>`<option value="${x.id}" ${x.id==c.id?'selected':''}>${icons[x.icon]} ${x.name}</option>`).join('')}</select></div><div class="field"><label>관리 년월</label><input name="managementMonth" type="month" value="${t.managementMonth||t.date?.slice(0,7)}" required></div><div class="field"><label>실제 사용일</label><input name="actualDate" type="date" value="${t.actualDate||t.date}" required></div><div class="field wide"><label>메모</label><input name="memo" value="${t.memo||''}"></div></div><button class="primary submit">수정 내용 저장</button></form>`;$('#modal').classList.remove('hidden');$('#entry-form').onsubmit=e=>submitForm(e,'transactionEdit')}

function openModal(type){$('#modal-body').innerHTML=templates[type]();$('#modal').classList.remove('hidden');const form=$('#entry-form');if(form)form.onsubmit=e=>submitForm(e,type)}
function closeModal(){$('#modal').classList.add('hidden')}
document.addEventListener('click',e=>{const close=e.target.closest('[data-close]');if(close){closeModal();return}const edit=e.target.closest('[data-edit-id]');if(edit){openTransactionEditor(edit.dataset.editId);return}const action=e.target.closest('[data-action]');if(action)openModal(action.dataset.action)});
async function submitForm(e,type){e.preventDefault();const data=Object.fromEntries(new FormData(e.target));['amount','principal','rate','principalAmount','interestAmount'].forEach(k=>{if(k in data)data[k]=Number(data[k])});if(type==='gemini'){const s=$('#gemini-status');s.textContent='연결 확인 중…';try{const r=await fetch('/api/gemini/test',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(data)}),j=await r.json();s.textContent=r.ok?'✓ '+j.message:'연결 실패: '+j.error}catch{s.textContent='서버 실행 후 테스트할 수 있습니다.'}return}
 let saved=false;if(type==='transactionEdit'){try{const r=await fetch('/api/transactions/'+data.id,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(data)});saved=r.ok}catch{}}else if(type!=='budget'){try{const endpoint=['income','expense'].includes(type)?'transactions':type==='repayment'?'repayments':type+'s';const r=await fetch('/api/'+endpoint,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({...data,amount:type==='repayment'?data.principalAmount+data.interestAmount:data.amount})});saved=r.ok}catch{}}
 if(type==='budget'){
   const items=state.categories.map(c=>({categoryId:c.id,name:String(data['category_'+c.id]).trim(),amount:Number(data['amount_'+c.id])||0}));
   try{const r=await fetch('/api/budgets/batch',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({month:data.month,items})});saved=r.ok}catch{}
   items.forEach(item=>{const c=cat(item.categoryId);c.name=item.name;const b=state.budgets.find(x=>x.category_id==item.categoryId&&(x.month||month)===data.month);b?b.budget=item.amount:state.budgets.push({category_id:item.categoryId,month:data.month,budget:item.amount,spent:0})});
 }
 if(type==='transactionEdit'){const t=state.transactions.find(x=>x.id===data.id);if(t)Object.assign(t,{title:data.title,amount:data.amount,category_id:Number(data.categoryId),managementMonth:data.managementMonth,actualDate:data.actualDate,memo:data.memo})}
 if(type==='income'||type==='expense'){state.transactions.unshift({...data,id:crypto.randomUUID(),category_id:type==='expense'?Number(data.categoryId):null,user:state.user})}
 if(type==='loan'){state.loans.unshift({id:'demo'+Date.now(),name:data.name,lender:data.lender,principal:data.principal,balance:data.principal,rate:data.rate})}
 if(type==='repayment'){const l=state.loans.find(x=>x.id===data.loanId);if(l)l.balance=Math.max(0,l.balance-data.principalAmount)}
 saveDemo();render();closeModal();toast(saved?'안전하게 저장했습니다':'이 기기에 저장했습니다')
}
$('#month').onchange=render;document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
function registerWebMCP(){const c=document.modelContext;if(!c?.registerTool)return;const ac=new AbortController();const tools=[{name:'add_expense',title:'지출 등록',description:'관리 년월과 실제 사용일을 포함해 생활비 지출을 등록합니다.',inputSchema:{type:'object',properties:{title:{type:'string'},amount:{type:'number'},categoryId:{type:'number'},managementMonth:{type:'string'},actualDate:{type:'string'}},required:['title','amount','categoryId','managementMonth','actualDate'],additionalProperties:false},async execute(i){if(!i.title||i.amount<=0||!cat(i.categoryId)||!/^\d{4}-\d{2}$/.test(i.managementMonth))throw new Error('유효한 지출 정보를 입력해 주세요.');state.transactions.unshift({...i,type:'expense',user:state.user,category_id:i.categoryId});saveDemo();render();return{status:'saved',title:i.title,amount:i.amount,managementMonth:i.managementMonth}}},{name:'read_month_summary',title:'월간 현황 조회',description:'선택한 관리 년월 기준 예산과 지출 요약을 조회합니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(){const m=$('#month').value,budget=state.budgets.filter(x=>x.month===m).reduce((s,x)=>s+x.budget,0),expense=state.transactions.filter(x=>x.type==='expense'&&(x.managementMonth||x.date?.slice(0,7))===m).reduce((s,x)=>s+x.amount,0);return{managementMonth:m,budget,expense,remaining:budget-expense}}}];tools.forEach(t=>c.registerTool(t,{signal:ac.signal}));}
loadDemo();state.budgets.forEach(b=>b.month||=month);state.transactions.forEach(t=>t.id||=crypto.randomUUID());state.categories.forEach(c=>{if(!state.budgets.some(b=>b.category_id==c.id&&b.month===month))state.budgets.push({category_id:c.id,month,budget:0,spent:0})});registerWebMCP();

